// Form에서 직접 keyword 가져오기
const formData = $('On form submission').first().json;
const blogUrl = formData.keyword;

// PC URL을 모바일 URL로 변경
const mobileUrl = blogUrl
  .replace('blog.naver.com', 'm.blog.naver.com')
  .replace('m.m.blog.naver.com', 'm.blog.naver.com');

// 현재 노드의 HTML 데이터
const htmlData = $input.first().json.data;

return [{
  json: {
    keyword: blogUrl,
    mobile_url: mobileUrl,
    html: htmlData,
    submittedat: formData.submittedat,
    formMode: formData.formMode
  }
}];

