// scene_img 필드에서 URL 추출
const sceneImg = $json.scene_img;

return {
  json: {
    ...$json,
    image_url: sceneImg
  }
};

const output = [];

for (const item of items) {
  try {
    // data.resultJson 문자열 파싱
    const result = JSON.parse(item.json.data.resultJson);

    // 첫 번째 URL 추출
    const url = result.resultUrls?.[0] ?? null;

    output.push({
      json: {
        url
      }
    });

  } catch (error) {
    output.push({
      json: {
        url: null,
        error: "Parsing failed: " + error.message
      }
    });
  }
}

return output;

const gptOutput = $input.first().json;

// OpenAI 응답 구조 파악
let extracted;

// 방법 1: output[0].content[0].text
if (gptOutput.output && gptOutput.output[0] && gptOutput.output[0].content) {
  const textContent = gptOutput.output[0].content[0].text;
  if (typeof textContent === 'string') {
    extracted = JSON.parse(textContent);
  } else {
    extracted = textContent;
  }
}
// 방법 2: message.content
else if (gptOutput.message && gptOutput.message.content) {
  extracted = JSON.parse(gptOutput.message.content);
}
// 방법 3: 직접 content
else if (gptOutput.content) {
  extracted = gptOutput.content;
}
// 방법 4: 이미 파싱된 경우
else {
  extracted = gptOutput;
}

return [{
  json: {
    keyword: $('모바일 URL 변경').first().json.keyword,
    mobile_url: $('모바일 URL 변경').first().json.mobile_url,
    title: extracted.title || '제목 없음',
    content: extracted.content || '',
    images: extracted.images || [], // 이제 [{url, context}, ...] 형태!
    image_count: (extracted.images || []).length
  }
}];

